/**
 * Golden tests of the rich text renderer against the legacy docutils output.
 *
 * - tests/fixtures/rst/legacy-examples.json: the ~75 examples of
 *   docs/reference/rst-rendering.md §8 (generated by the real legacy code).
 * - tests/fixtures/rst/legacy-corpus.json: every distinct context / header /
 *   choice / description of the sample courses + examples/demo-tasks rendered by the
 *   legacy frontend (regenerate with tests/fixtures/rst/collect-corpus.mjs).
 * - tests/fixtures/rst/markdown-examples.json: Markdown mode.
 * - a live scan of the YAML files: nothing may fall back to "Parsing failed".
 *
 * Comparison is modulo insignificant whitespace (around tags, runs of spaces)
 * and after passing the legacy output through the same sanitizer, so the
 * intentional sanitizer changes (no <script>, target/rel on links) are not
 * reported as differences. Every other difference is listed in DEVIATIONS.
 */
import { describe, expect, it } from 'vitest';
import fs from 'node:fs';
import path from 'node:path';
import YAML from 'yaml';
import { renderText, type RenderOptions } from './index.js';

// The legacy outputs were generated on a UTC server (naive hidden-until dates are local).
process.env.TZ = 'UTC';
import { sanitize } from './sanitize.js';

/** Reads a JSON fixture of tests/fixtures/rst. */
function fixture<T>(name: string): T {
	return JSON.parse(fs.readFileSync(path.join('tests/fixtures/rst', name), 'utf8')) as T;
}

/** Removes insignificant whitespace (keeps a single space between words). */
function normalize(html: string): string {
	return html
		.replace(/\s*(<[^>]+>)\s*/g, '$1')
		.replace(/\s+/g, ' ')
		.trim();
}

/** Fixed clock: after the "past" hidden-until dates, before the "future" ones. */
const NOW = new Date('2026-01-01T00:00:00Z');

/** Per-example render options (the §8 generator used these settings). */
const OPTIONS: Record<string, RenderOptions> = {
	hidden_until_future_show_everything: { showEverything: true },
	static_page_level2: { headerLevel: 2 },
	lti_rewrite: { ltiAssetRewrite: (url) => `asset/${url}?session_id=abc123` }
};

/**
 * Intentional deviations from the legacy output, with the output we produce instead.
 * Keys are §8 example names.
 */
const DEVIATIONS: Record<string, { reason: string; html: string }> = {
	syntax_error_inline: {
		reason: 'rst-compiler does not report inline markup warnings; the text is kept verbatim',
		html: '<p>*unclosed emphasis</p>'
	},
	syntax_error_bad_table: {
		reason: 'only the "Malformed table." error is reported, not the follow-up "Blank line required" warning',
		html:
			'<div class="system-message"><p class="system-message-title">System Message: ERROR/3 (<tt class="docutils">&lt;string&gt;</tt>, line 1)</p>' +
			'<p>Malformed table.</p><pre class="literal-block">+---+ | a | +--</pre></div>'
	},
	footnote: {
		reason:
			'footnote ids come from rst-compiler (footnotedef-N / footnoteref-N instead of footnote-N / footnote-reference-N)',
		html:
			'<p>Text<a class="footnote-reference" href="#footnotedef-1" id="footnoteref-1">[1]</a>.</p>' +
			'<table class="docutils footnote" id="footnotedef-1" frame="void" rules="none"><colgroup><col class="label" /><col /></colgroup>' +
			'<tbody valign="top"><tr><td class="label"><a class="fn-backref" href="#footnoteref-1">[1]</a></td><td>Note.</td></tr></tbody></table>'
	}
};

/** Corpus entries (file + key) whose output intentionally differs from legacy. */
const CORPUS_DEVIATIONS: Record<string, string> = {
	'infra/tasks/task_showcase/task_info/task.yaml context':
		'SVG images are rendered as <img> (docutils used <object>, removed by the sanitizer)',
	'infra/tasks/tutorial/04_run_student/task.yaml context':
		'option list with descriptions on the next line is rendered as a definition list',
	'infra/tasks/tutorial/08_feedback/task.yaml context': 'option list rendered as a definition list (same reason)',
	'infra/tasks/tutorial/09_advance_feedback/task.yaml context':
		'option list rendered as a definition list (same reason)'
};

describe('§8 legacy examples', () => {
	const examples = fixture<{ name: string; rst: string; html: string }[]>('legacy-examples.json');

	it('contains every example of the spec', () => {
		expect(examples.length).toBeGreaterThanOrEqual(75);
	});

	for (const example of examples) {
		// "html" mode (pytidylib) has no production caller and is not ported: no golden test.
		if (example.name.startsWith('html_mode')) continue;
		it(example.name, () => {
			const html = renderText(example.rst, { now: NOW, ...OPTIONS[example.name] });
			const expected = DEVIATIONS[example.name]?.html ?? sanitize(example.html);
			expect(normalize(html)).toBe(normalize(expected));
		});
	}
});

describe('legacy corpus (infra/tasks + examples/demo-tasks)', () => {
	const corpus = fixture<{ file: string; key: string; rst: string; html: string }[]>('legacy-corpus.json');

	it.each(corpus.map((entry) => [`${entry.file} ${entry.key}`, entry] as const))('%s', (id, entry) => {
		const html = normalize(renderText(entry.rst, { now: NOW }));
		if (CORPUS_DEVIATIONS[id]) expect(html).not.toBe(normalize(sanitize(entry.html)));
		else expect(html).toBe(normalize(sanitize(entry.html)));
	});
});

describe('live task files', () => {
	/** Yields the YAML files below a directory. */
	function* walk(dir: string): Generator<string> {
		for (const entry of fs.readdirSync(dir, { withFileTypes: true })) {
			const file = path.join(dir, entry.name);
			// e2e_* courses are temporary copies of the integration fixtures (some invalid on purpose).
			if (entry.isDirectory() && !entry.name.startsWith('e2e_')) yield* walk(file);
			else if (entry.name.endsWith('.yaml')) yield file;
		}
	}

	it('renders every context, header, choice and description without "Parsing failed"', () => {
		const failures: string[] = [];
		let count = 0;
		for (const root of ['tests/fixtures/sample-courses', '../examples/demo-tasks'].filter((d) => fs.existsSync(d))) {
			for (const file of walk(root)) {
				let doc: Record<string, unknown> | null;
				try {
					doc = YAML.parse(fs.readFileSync(file, 'utf8')) as Record<string, unknown> | null;
				} catch {
					continue; // not a task/course descriptor
				}
				const texts = [doc?.context, doc?.description];
				for (const problem of Object.values(
					(doc?.problems ?? {}) as Record<string, { header?: unknown; choices?: { text?: unknown }[] }>
				)) {
					texts.push(problem?.header, ...(Array.isArray(problem?.choices) ? problem.choices.map((c) => c?.text) : []));
				}
				for (const text of texts.filter((x): x is string => typeof x === 'string')) {
					count++;
					const html = renderText(text, { now: NOW, random: [0.25] });
					if (html.includes('Parsing failed') || html.includes('system-message')) failures.push(file);
				}
			}
		}
		expect(count).toBeGreaterThan(100);
		expect(failures).toEqual([]);
	});
});

describe('markdown examples', () => {
	const examples = fixture<{ name: string; markdown: string; html: string }[]>('markdown-examples.json');
	for (const example of examples) {
		it(example.name, () => {
			expect(normalize(renderText(`#MD\n${example.markdown}`, { random: [0.5] }))).toBe(normalize(example.html));
		});
	}
});
